quests[34288] = { id = 34288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Totems That Bind", description = "Before Borgal began to use the Soulgrinder, he used totems to bind spirits to his service.\n\nIf we can get a few of those totems I may be able to use the spiritual connection he's forged with them to force a link. He'll be compelled to appear before us!\n\nGo find me a few of those totems and I might be able to pull this off, I think five should do it.", progress = "Do you have those totems I asked for? He left them around the buildings nearby.", completion = "Very good, I can feel that the magic in these is strong.", objectives = "Collect 5 of Borgal's Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34289] = { id = 34289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulgrinder Survivor", description = "It is time for Borgal to die.\n\nWe must travel to a location of power where I have room for the ritual. There is a ruined tower to the northwest that will be perfect for this. Meet us there and place the totems in the areas of power you will find there. Once they are placed I will do the ritual that will summon Borgal to us.\n\nYour job will be the difficult one, kill him!", completion = "That was one hell of a battle! Bloody fine job there la... um commander. \n\nOrlana really helped us out there. I'll ask around, maybe a priest can think of something we can do for her. \n\nAt any rate, we still have this artifact to deal with. I think you better hold onto it for safe keeping before any power crazed lunatics comes looking for it.", objectives = "Place Borgal's totems so that Orlana can begin the ritual, then kill Borgal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34290] = { id = 34290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ketya's Stash" }
quests[34291] = { id = 34291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Have a Heart", description = "Did you notice the magical barrier protecting the cave's entrance? It's being powered by demon crystals.\n\nThe Burning Legion has a habit of making demon parts serve as the keys to such devices.\n\nTravel west to the Ruins of Ata'gar. Look for a powerful demon therein and bring me its heart.\n\nI'll project an image of myself into the ruins. You won't have to come back here until we're done.", progress = "Do you have the demon key?", completion = "A heart? How touching.\n\nQuickly. We must use it to destroy the fel crystals and get to Gul'dan.", objectives = "Collect the Heart of Fernus from Fernus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34292] = { id = 34292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Shadow Council", description = "Those ruins are going to be full of Shadow Council flunkies. We can't afford to let them scatter all over Draenor once you've dealt with Gul'dan.\n\nNo, we need to eliminate every one of them down to the last orc.", completion = "Necessary business. We don't dare risk letting them grow more powerful.", objectives = "Kill 12 Shadow Council members at the Ruins of Ata'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34293] = { id = 34293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminate the Shadow Council", description = "These ruins are full of Shadow Council adherents. We can't afford to let them scatter all over Draenor once Gul'dan has been dealt with.\n\nNo, we need to eliminate every one of them down to the last orc.", completion = "Necessary business. We don't dare risk letting them grow more powerful.", objectives = "Kill 12 Shadow Council members at the Ruins of Ata'gar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34294] = { id = 34294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fel Crystals", description = "You have the key. Now use it to destroy the fel crystals.\n\nOnce they are eliminated, the magical barrier blocking the entrance to the Gloomspire will come down.\n\nAnd once the barrier is down, you'll go inside to confront Gul'dan.", progress = "Is there a problem?", completion = "The barrier is down. Now it's time to capture Gul'dan.", objectives = "Destroy the Fel Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34295] = { id = 34295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Capture Gul'dan", description = "Gul'dan is in the cave further into the Gloomspire.\n\nWe know that he's about to leave for Talador and Shadowmoon Valley. You must capture him by any means necessary, {name}.\n\nI'll see you back at Throm'var. Good luck.", completion = "Unfortunate, but not surprising. At least we were able to defeat one of the inner council members.\n\nAll is not lost, {name}. We know what the Shadow Council is up to and where they're heading.\n\nWe'll regroup in Talador. Together, we'll put an end to Teron'gor and his plans for Auchindoun.\n\nDid you hear that?...", objectives = "Confront Gul'dan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34299] = { id = 34299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Threat We Can't Ignore", description = "Ishnu-alah, {name}. I trust that Khadgar and Mathias have adequately briefed you on this situation here in Grommar. Time is of the essence, so I will be brief.\n\nThe Iron Horde presence here represents an immediate threat to the safety of Shadowmoon Valley. Grommar has been receiving supplies and reinforcements via the harbor for some time now.\n\nThe most concerning of these reinforcements are the battleships docked in the harbor. Place these explosives on the nearest battleship undetected and report back.", objectives = "Plant the Underwater Explosives on the Iron Horde battleship.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34304] = { id = 34304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutation Station", description = "Grulk very weak...barely stand.\n\nGrulk not always look this way. Grulk once was orc...Iron Horde make Grulk mutant. Grulk angry at Iron Horde...so Iron Horde lock Grulk in cage...hurt Grulk.\n\nGrulk HATE Iron Horde...Grulk want SMASH them...make them PAY!\n\nTake serum...use on Grulk to make Grulk strong! Help Grulk SMASH Iron Horde!", objectives = "Assist Grulk in destroying the Mutation Lab by administering the Mutation Serum to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34309] = { id = 34309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Search for Shadow Hunter Bwu'ja", description = "It be a long time since we hear from Shadow Hunter Bwu'ja, commander. \n\nLast we know she be on assignment keeping an eye on dem Bloodmaul ogres up in Frostfire.\n\nDem ogres just be a bunch a slavers so something really big must be happening ta keep her from reporting in.\n\nGo over ta de Stonefury Cliffs an' find her.", completion = "Oi dere mon! Glad to see a friendly face but I not expect da commander ta come out here for me himself!", objectives = "Travel to the Stonefury Cliffs and search for Shadow Hunter Bwu'ja.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34311] = { id = 34311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Invasion: Opted Out" }
quests[34312] = { id = 34312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Magma Lord" }
quests[34313] = { id = 34313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orlana Strongbrow" }
quests[34314] = { id = 34314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Chains", description = "Lissen mon, dem ogres, got da jump on me wid an artifact wid powerful mojo. Next t'ing I know I wake here wid broken bones an' dis chain on me leg. I called to da spirits ta break it, but da spirits here no answer.\n\nGotta go wid da old methods ta get out. Dere be a big ogre in da cave here called Rugrum who has da key to me shackle. Could ye go put a blade in his belly and get me dat key?", progress = "You no worry about me, mon. I be going nowhere.", completion = "Ah now, dat be feeling much better!", objectives = "Obtain the Bloodmaul Slave Key and free Shadow Hunter Bwu'ja.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34315] = { id = 34315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gearing Up", description = "Dem ogres whipped me real good. My arm be broke, a few ribs snapped, t'ink even me spleen be hurtin' from dat beatin'. Nothin' a troll can't handle though but I be needin' a moment ta recover.\n\nWhat I really be needin' is me gear dem ogres took from me. Dey got me garb in a chest near a hut to da south, me glave in a chest next to da tower wid da Bonecrushers, dey even got me mask, it over near da lava! Could ye go find dem while I take a breather?", progress = "Ah, hear dat? T'ink anudda rib just popped back inta place.", completion = "Ah dat be me stuff! Give me a moment ta put me stuff on mon. Then, I gonna take me an ogre ear for every bone I had ta pop back in place.", objectives = "Obtain Bwu'ja's garb, glave, and mask.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34316] = { id = 34316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking the Truth", description = "Lissen mon, a few nights ago dem ogres found a bit o' old and powerful mojo.\n\nI was snooping around da cave across de lava flows when dere was a huge scream from da spirit world. I went in and saw Borgal, de ogre chief, he be draining da spirits from de slaves wid some big stone wheel dat I heard dem call de Soulgrinder. I tried ta take 'em out but a single shot from dat thing took all de strength from me.\n\nDat mojo too much of a threat in de hands of dem ogres.", completion = "This be da place. We gonna need ta be careful, Borgal an' da artifact be in there.", objectives = "Locate Borgal Doomfist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34318] = { id = 34318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Totems That Bind", description = "Before Borgal began to use the Soulgrinder, he used totems to bind spirits to his service.\n\nIf we can get a few of those totems I may be able to use the spiritual connection he's forged with them to force a link. He'll be compelled to appear before us!\n\nGo find me a few of those totems and I might be able to pull this off, I think five should do it.", progress = "Do you have those totems I asked for? He left them around the buildings nearby.", completion = "Very good, I can feel that the magic in these is strong.", objectives = "Collect 5 of Borgal's Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34319] = { id = 34319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulgrinder Survivor", description = "It is time for Borgal to die.\n\nWe must travel to a location of power where I have room for the ritual. There is a ruined tower to the northwest that will be perfect for this. Meet us there and place the totems in the areas of power you will find there. Once they are placed I will do the ritual that will summon Borgal to us.\n\nYour job will be the difficult one, kill him!", completion = "Dat was a battle for da ages mon! Bwu'ja be glad ye are here commanda, else I'd likely be back in da spirit world permanently.\n\nDat Soulgrinda be a nasty piece o' mojo. Ye be the best one to hold onto it.\n\nDat spirit, she helped us out a lot mon. I hope she find da peace she be seeking now.", objectives = "Place Borgal's totems so that Orlana can begin the ritual, then kill Borgal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34321] = { id = 34321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashes Of The Past", description = "The ogres are a plague upon my kind. They summon my kin and force them into servitude, working them without rest till their heat fades away and they crumble into dust.\n\nTheir ashes must return to the lava flows so that they can be reborn!\n\nThe Ogres keep the dust in pouches on their person thinking it would enhance their strength. Go slay them and recover the ashes of my people!", progress = "Do you bring me the remains of our fallen?", completion = "Thank you flesh creature. In the lava the ashes will mix and the cycle shall continue as it has ever since the beginning.", objectives = "Molthron within the Bloodmaul Territory wants you to bring him 6 Piles of Elemental Ash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34325] = { id = 34325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flames Of The Earth", description = "I've searched the depths of the earth and found the means to break the spells that hold my people captive, but it only functions to free one who is completely bound. I would be unable to prevent myself from becoming bound by the same magic.\n\nYou, flesh creature, are not of the flames below so their binding spells should not affect you.\n\nPlease take my jewel, use its power to free my people!", progress = "Do my people have their freedom?", completion = "The lava already burns bright with the return of my people's freedom!\n\nWe will have our revenge upon the ogres for everything they have done to us, this I assure you. But for now, we shall rest.", objectives = "Molthron within the Bloodmaul Territory wants you to use the Flamewrought Jewel to free 6 Magma Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34326] = { id = 34326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Changing the Tide", description = "It is time to retaliate against this foe. Meet me at Retribution Point and we will take this fight to the Shadow Council.\n\nTeron'gor shall not feast on another soul so long as we stand in his way! His reign of terror ends today.", completion = "Our enemy has been pushed back and Auchindoun's defenses restored thanks to your help, but we are not yet done here.", objectives = "Speak to Restalaan at Retribution Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34327] = { id = 34327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonus Objective: Kill Ogron" }
quests[34328] = { id = 34328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of the Wolf Selected" }
quests[34329] = { id = 34329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buffeting Galefury Selected" }
quests[34330] = { id = 34330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogrish Fortitude Selected" }
quests[34331] = { id = 34331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Wolf Selected" }
quests[34332] = { id = 34332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touched by Fire Selected" }
quests[34333] = { id = 34333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touched by Ice Selected" }
quests[34335] = { id = 34335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Crows In The Field", description = "Our druids set up a wide network of scouts to follow up on your intel from Nagrand.\n\nWe've identified a suspicious Iron Horde excavation near some salt pools on the western coast of Gorgrond.\n\nWe have reason to believe that these orcs are pursuing a valuable artifact deep in the desert.\n\nI'm putting together a small mission for a focused, surgical strike, and we could use a capable {class} like yourself. I'd like you to be part of that team.", completion = "Greetings, {class}. You're the commander that Choluna mentioned?\n\n\n\nGood.", objectives = "Speak to Thisalee Crow at Skysea Ridge in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34336] = { id = 34336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ambushing the Enemy", description = "See that Iron Horde camp to the south, across the water? We've been watching their movements for days.\n\nWe've seen a lot of correspondence between their lieutenant and the Iron Horde command in Nagrand.\n\nWe need to disrupt their operation.\n\nGather their supplies, and bring me their leader's head.", progress = "Those orcs were working on someone else's orders.", completion = "I knew you were the right person for this job, {name}. I just love results.", objectives = "Collect 5 Caravan Shipments and Lieutenant O'rok's Head.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34337] = { id = 34337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Giant Cauldron", description = "A high value artifact at Cragplume Canyon, hmmm?\n\nLet's see if we can't beat the Iron Horde to it.\n\nLet's move fast. Speak to Choluna, and we'll be on our way.", completion = "So this is it, huh? Let's see what's hiding in these depths.", objectives = "Speak to Choluna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34338] = { id = 34338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Descent", description = "Whatever lies at the bottom of this cauldron is of great use to the Iron Horde, and therefore, of great interest to us.\n\nI need you to investigate the bottom of this crater.\n\nYou go ahead. I'll be right behind you.", progress = "<Thisalee looks at you coolly.>", completion = "That was close, {name}. Good work.", objectives = "Investigate Cragplume Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34339] = { id = 34339, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Goren's Feast", description = "Goren. This caldera is full of them. I can even smell their stench from here.\n\nI suspect that these goren are more than just primitive beasts, but in order to prove my theories, I need more data.\n\nDuring your mission, if you should slay a goren or two, would you examine their stomachs for me? I'd like to know what these curious creatures eat.", completion = "Oh my, what an interesting variety! It appears that the goren will eat... anything!", objectives = "Collect 8 Engorged Stomachs and examine their contents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34340] = { id = 34340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heating Up", description = "Greetings, {name}. I have been conducting research on the steam geysers of Gorgrond for some time now.\n\nCragplume Cauldron is one of the largest caldera in this region, but we have been unable to do a geographical survey due to the dangerous creatures in this area.\n\nSince you are venturing into the depths, could you take a temperature reading for me?\n\nIt would add greatly to our understanding of these natural caverns.", completion = "Oh, my! Amazing! This caldera is hotter than hot! Thank you, {name}.", objectives = "Use Aren's Thermometer near the Hissing Geyser inside Cragplume Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34341] = { id = 34341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beating Heart", description = "One thing is certain. We now possess an item of great value to the Iron Horde.\n\nWe had better secure this... \"Heart of Gorgorek\" at once.", completion = "Good. We will keep the artifact safe here, in your garrison.", objectives = "Deliver the Heart of Gorgorek to Warmaster Zog at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34343] = { id = 34343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonus Objective: Kill Frostiron Magnaron" }
quests[34344] = { id = 34344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lurkers", description = "Dis be a dangerous place, boss-mon.\n\nFilled with big monsters and savage giants.\n\nWell, like my family loa say, 'If ya can't beat it, poison it.'\n\nWe gonna be needin' some venom from the lurkers out there on the Cracking Plains. Dem lurkers be mighty sneaky, and mighty creepy. Be watchin the ground for rumbles and shakes.\n\nI'll be stayin' here to make a cure in case you accidentally get too poisoned.", progress = "Dem lurkers scare ya off?", completion = "Dem centipedes creep you out boss-mon? Touchin' ya with their teeny tiny legs? I ain't thought of a thing that makes me skin crawl more, except maybe mah sister's voice. Hee hee.", objectives = "Collect 8 doses of Lurker Venom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34345] = { id = 34345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poulticide", description = "We be huntin' something so big, so savage, we gonna need anotha poison. We gonna need a big ol' poultice of poison!\n\nSo...  boss-mon? Ya think ya up for a little flower pickin'? We gonna need the leaves of them frostbloom plants that be growing along the shadows of rocks and ledges along the sides of the Cracking Plains.\n\nBe careful when pickin' them,  boss-mon! They not always be by themselves...", progress = "I'd pick de flowers myself, but I got allergies. Ha ha!", completion = "Haha! Ya brought 'em! I hope ya not offended I asked such a lowly task of ya. We needed the leaves, and I needed to settle a bet.", objectives = "Collect 10 Frostbloom Leaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34346] = { id = 34346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frosted Fury", description = "The furies of Draenor are different than the elementals of Azeroth. But don't be fooled. Some be wicked, boss-mon. Wicked.\n\nThe trap we are making be needing some proper frostshards. You can get them, if ya willing, from the ice furies.\n\nDey be wandering the Cracking Plains, freezin' all dat dey touch, an' bein' wicked.\n\nBring us some o' these frostshards,  boss-mon, an' we gonna whip ya up one deadly trap.", progress = "A shadow huntah knows much of da spirits. We be talkin'. We be tradin'. But these ice furies, dey be wicked,  boss-mon.", completion = "Ah, now these be some fine trap making props. Ya know how to make a shadow huntah proud.", objectives = "Collect 3 Frostshards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34347] = { id = 34347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bladefury's Orders", description = "Lieutenant O'rok:\n\nSend an elite strike team to Cragplume Cauldron.\n\nRetrieve a high-value artifact from the crater and deliver it to my command post in northern Talador.\n\nWith your remaining forces, go to Gorgorek's Fall. Protect and prepare the ancient magnaron specimen for retrieval.\n\nImmediate action is required.\n\n- Bladefury", completion = "These orders come straight from the leader of the Burning Blade!\n\nI've heard of her... the fierce orc with the blade that thirsts for death.\n\nYou've done well to bring this to me, {name}.", objectives = "Deliver Bladefury's Orders to Thisalee Crow at Skysea Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34348] = { id = 34348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Real Prey", description = "Eh boss-mon. Time for us to be huntin' the real prey now. To the north, there be a cave. In the cave, there be right mean ogron dey call \"Grosh the Mighty.\" That ogron got a big stash of pillaged hides and leathers we gonna be needin' for the troops at the garrison.\n\nI made a special poison from the stuff ya gathered. Dis be a magic poison, and it gonna put that ogron down to sometin' a bit more manageable. \n\nTake these vials to the cave and see if ya can't win us a treasure.", progress = "Why be killin' five hundred clefthoof when ya can just kill one big ogron dat killed five hundred clefthoof?", completion = "Now dat be a mighty fine haul. We gonna be keepin' all the folks at the garrison warm.\n\nIt seemed like a simple task but ya tackled it like a boss-mon. If ya need a shadow hunter in your ranks, I be willin' to serve.", objectives = "Find Iceblister Den and then slay Grosh the Mighty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34351] = { id = 34351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Must Construct Additional Pylons", description = "We came here to retrieve a reserve pylon to power Auchindoun's defenses, but we've been pinned to this position by the Shadow Council for hours!\n\nI need to get these injured back to Exarch's Refuge, but we still need the backup system!\n\nPlease, gather Arkonite crystals and an Arkonite pylon from the tomb and meet me at the refuge as quickly as you can!", progress = "Do you have the arkonite pylon and the crystals?", completion = "Light bless you, hero! We need to hold out as long as we can so Nyami can track down the remaining power shards. This pylon will help take the load off of our soulpriests.", objectives = "Collect 6 Arkonite Crystals and an Arkonite Pylon from the Tomb of Lights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34352] = { id = 34352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darktide Defender", description = "<Rexxar looks at you as you inspect the dead goblin. It's clear what he wants you to do.>", objectives = "Kill 5 Darktide Pilferers and 5 Darktide Engineers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34353] = { id = 34353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Suppressor", description = "The rylaks have no defense against the Iron Horde's technology. A true hunter would not need machines to capture their prey.\n\nDestroy the Iron Shredders and the scum that pilot them. Spirit will join you on your quest.", completion = "You are proving to be a great hunter, {name}. But our work on this island is not yet complete.", objectives = "Destroy Darktide Shredders on Darktide Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34354] = { id = 34354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Good Death", description = "These fools have no honor.\n\nThey seem to enjoy torturing these poor beasts. The only humane thing we can do at this point is find injured rylaks and put them out of their misery.\n\nTake this axe and aim for their vitals, {name}.  These rylaks deserve a good death.", completion = "You have done a good thing here today. Don't let the blood on your axe blind you.\n\nYou have given these rylaks the peace they deserve.", objectives = "Use Rexxar's axe to kill Injured Rylaks at Darktide Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34355] = { id = 34355, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirty Rats", description = "These shredders are more of a hassle than I expected.\n\nI've been peering through the eyes of the rats on the island. There are number of unmanned shredders west of here.\n\nThe rats have an uncontrollable appetite for this bait. Throw it onto Unmanned Shredders and let the rats destroy them from the inside.", completion = "With fewer machines these weaklings will quickly lose their foothold on this island.\n\nExcellent work, {name}.", objectives = "Use the rats to destroy Unmanned Shredders on Darktide Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34359] = { id = 34359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darktide Defender TEST" }
quests[34360] = { id = 34360, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "SHWAYDER TEST" }
quests[34361] = { id = 34361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: The Bone Crawler" }
quests[34362] = { id = 34362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Gate", description = "Okay, we're gonna have to be quick. \n\nI've seen Borgal form magical portals before so he might try to use one to escape. If he does that our only option will be to follow after 'em. On top of that he always keeps his lieutenant Grubnor nearby so we may have a bit of a tussle in store.\n\n<Owynn peeks into the cave.>\n\nKeep yer head down, something's going on in there.", completion = "Blast it, he's given us the slip!\n\nTa make things worse the portal looks like it's closed from this side. We're gonna have to find a way to track Borgal down or we might be stuck in wherever this is.", objectives = "Defeat Grubnor Wargut and follow after Borgal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34364] = { id = 34364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Horde!", description = "Without you, none of us would have made it to the shores of my homeland. You will be the one to lead our forces here on Draenor. This is your garrison to found.\n\nI leave it to you to plant the banner and claim this territory. When you are ready, I will have Khadgar open a portal to bring through a few necessary reinforcements.", completion = "I'm under orders to obey your orders, commander.", objectives = "Plant the Horde Banner to Claim the Land.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34365] = { id = 34365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Releasing Rylak", description = "These goblins have been conducting horrible experiments on the rylaks. This fool gave me the location for three of their prized experiments.\n\nSet these mutated rylaks free. Maybe freedom will help these tortured souls find some peace in life.", completion = "Excellent work, {name}. You are proving to be a great ally.", objectives = "Free the Caged Rylaks on Darktide Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34366] = { id = 34366, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tanaan 01: Front of the Portal", description = "- Gul'dan will ask you for freedom, which you ignore.\n\n-You plant your mana bomb but it doesn't work.\n\n-Khadgar concedes and you kill felbreakers to free Gul'dan.\n\n-A noble NPC leads the distraction sacrifice troops while you and Khadgar escape 'round back." }
quests[34375] = { id = 34375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Work", description = "Alright, boss. We're gonna need some lumber if we're gonna get this garrison started off right.\n\nIf you mark some trees to be cut down, your peons will do the rest.", progress = "There aren't a lot of trees around. Go mark 'em!", completion = "That should be plenty of wood for now.", objectives = "Mark 6 Trees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34376] = { id = 34376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ore Not to Be", description = "Okay, commander, here's the deal. You're gonna want spikes and all sorts of cool stuff on your garrison, right? To get started, we'll need some ore from a nearby cave.\n\nCheck out that cave to the southeast of us. Knowing what I know from being here for a no time at all, I bet there's something big and nasty inside.\n\nTake care of it and the peons will get the ore for ya.", objectives = "Kill Munch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34377] = { id = 34377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Portal Home" }
quests[34378] = { id = 34378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establish Your Garrison", description = "It's time for the main event! We've got the materials, we've got the manpower, we've got another thing that starts with \"m.\"\n\nLet's build this thing!\n\nI got a gaggle of assistants up on that ridge to the west.\n\nThey should have your personal surveying stand set up by now.\n\nHead on over there and you should be able to watch our progress from it.", progress = "I'm almost as excited about building this as you are. I want to see if it falls apart!", completion = "Right! I think we've got this well in hand now. And hardly an explosion to be found!", objectives = "Watch the construction of your garrison by using the Master Surveyor", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34379] = { id = 34379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den of Wolves", description = "Durotan wishes for us to join him now that you have established your foothold. I hope he will accept your help.", completion = "I hope you are finding your land agreeable.", objectives = "Ride the Frostwolf Rylak to Wor'gol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34380] = { id = 34380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Frostwolves", description = "My brother, in his haste, has already taken some of my clan with him and has begun an assault on Bladespire Citadel before we were ready.\n\nDraka awaits by our war horn. Please let her know that it is time to rally the clan!\n\nWith the aid of you and your forces, we might actually stand a chance at victory against the ogres.", progress = "Draka will know what to do.", completion = "The clan is prepared. It is time for us to advance on Bladespire Citadel!", objectives = "Ask Draka to sound the war horn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34381] = { id = 34381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Gate", description = "Dere be ogres in da cave, I smell de stink of 'em.\n\nKeep ye weapon handy, we gonna have ta move quick and take down de ogres before dey start tossing da mojo.\n\n<Bwu'ja peeks into the cave.>\n\nWatch ye self mon, something be going down in dere.", completion = "Dat ogre, he done give us de slip!\n\n<Bwu'ja looks around.>\n\nDis place, it be da spirit world! First time I ever walk here in da flesh.\n\nLooks like our path back be blocked and our prey be gone. We gonna have ta go find dat ogre ta get outta dis place.", objectives = "Defeat Grubnor Wargut and follow after Borgal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34382] = { id = 34382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grand Warlock Duress" }
quests[34392] = { id = 34392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Onslaught's End", description = "\"Guard Gul'dan and his Shadow Council with your lives! The portal cannot function without our prisoners' fel magic. Fail me and watch all that you hold dear turn to ash.\n\n-Grommash Hellscream.\"\n\nThe Iron Horde appear to be holding prisoners that are crucial to keeping the portal open. Search the nearby spires!", progress = "See the drifting energy from the tips of those spires? They clearly have some effect upon the portal.\n\nWith any hope, the portal falls along with them.", completion = "The portal is weakened, but it remains open.\n\nOnly one option remains, {name}.", objectives = "Disable the two fel spires of the Dark Portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34393] = { id = 34393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Portal's Power", description = "This portal is fueled by powers neither mechanical nor arcane.\n\nLook to either side of us, {name}. The screaming souls of slain prisoners are being channeled into the heart of the portal itself.\n\nAnd they are channeling these souls through the body of Gul'dan.\n\nFind a way into the chamber beneath us, and do whatever it takes to get Gul'dan to stop his channeling. Our last hope rests on you, {name}.", progress = "Go now, hero! Lives hang in the balance!", completion = "Gul'dan... free. This was not the victory I'd planned for.\n\nGul'dan may be loose due to our actions, but I gladly bargain his freedom against the lives of the innocents on the other side of this portal. You made a wise decision, {name}.", objectives = "Enter the Soul Engine beneath the Dark Portal, then shut the Dark Portal down.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34397] = { id = 34397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Downsizing the Darktide", description = "This pathetic excuse for life sold out all of his companions. All it took was a little squeeze of the neck.\n\nFind the leaders of this operation and bring me their heads. Haratha will accompany you on your quest.", progress = "The Iron Horde have no concept of honor.", completion = "With their leaders dead this operation will surely fall apart.", objectives = "Takedown the Darktide leadership.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34398] = { id = 34398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords of Draenor: The Dark Portal", description = "Archmage Khadgar, hero of the Second War, is assembling a coalition of Azeroth's strongest to bravely step through the Dark Portal and stop the Iron Horde's invasion of Azeroth.\n\nChampions who are interested in glory can meet Khadgar at the base of the Dark Portal in Blasted Lands.\n\nSafety not guaranteed.", completion = "Looks to me like we ended up in the right place.", objectives = "Speak with Archmage Khadgar at the foot of the Dark Portal in Blasted Lands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34399] = { id = 34399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble In The Mine", description = "The Jorune Mine is in trouble!\n\nWe recently unearthed an exceedingly large and powerful arcane crystal; however, something has gone terribly wrong and the energy from the crystal is flooding the mine.\n\nThe Auchenai have already sent their Vindicators into the mine to assist us.\n\nSpeak with Vindicator Doruu inside of the mine, he'll know how you can help.", completion = "The Vindicators welcome you, {name}.", objectives = "Speak with Vindicator Doruu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34400] = { id = 34400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frenzied Manafeeders", description = "There is a rare breed of moth in Talador known as the Manafeeder. These moths sustain themselves by feeding on arcane crystal dust from the mine.\n\nTypically speaking, these moths are nothing more than an occasional nuisance. However, they are now gorging themselves upon the intense arcane energy flooding out of the mine and have become highly territorial and aggressive.\n\nI have attuned this crystal to disperse arcane energy. Please use it on the Frenzied Manafeeders to soothe them.", progress = "Have you used the Arcane Dissipator on the Manafeeders yet?", completion = "Thank you, {name}. These moths are typically peaceful creatures and are deserving of mercy.", objectives = "Use the Arcane Dissipator on 8 Frenzied Manafeeders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34401] = { id = 34401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Essence", description = "Kaelynara will not stop until she has drained every last drop of arcane energy from the crystal...and destroyed this entire mine in the process. The arcane shield she guards herself with cannot be penetrated by normal means, but I have a plan.\n\nIf I had a focusing crystal powerful enough to momentarily pierce her shield, Kaelynara could then be dealt with.\n\nFortunately, we are in the perfect place to build one. Start by bringing me arcane essence from the creatures rampaging throughout the mine.", progress = "Have you retrieved the arcane essence for me?", completion = "This will do nicely, {name}. All we need now is a suitable crystal...", objectives = "Retrieve 6 Arcane Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34402] = { id = 34402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Wolves and Warriors", description = "The return of many of my people is a boon to us, and I thank you for your part in their survival.\n\nCome, ride with me. We have much to discuss.", completion = "This land should serve our needs well. I leave it to you to decide how to best use it, commander.", objectives = "Ride with Durotan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34403] = { id = 34403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Essence", description = "Kaelynara's lust for arcane power has consumed her and she threatens the safety of all in this mine. She must be stopped.\n\nUnfortunately, there is nothing we can do while she shields herself. We will need to find a way to penetrate her shielding spell.\n\nPerhaps if I were to build a focusing crystal, I could use it to lower her shield...I'll need you to search the crystal mine for the necessary components.\n\nFirst, I'll need arcane essence from the Crystal Ragers and Arcane Wraiths in the mine.", progress = "Have you collected enough arcane essence yet?", completion = "Excellent work, {name}. The arcane essence you've collected will do nicely. All we need now is a suitable crystal to attune...", objectives = "Retrieve 6 Arcane Essence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34404] = { id = 34404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystals of Unusual Power", description = "Arcane crystals of this size and power are quite rare even on Draenor. It is no coincidence that the Draenei built Shattrath and Auchindoun so close to this mine.\n\nI am interested in learning more about these particular crystals and their arcane nature.\n\nReturn to me with any unrefined power crystals that you may find and I will make sure that you are adequately compensated for your effort.", progress = "Have you collected the unrefined power crystals I need for my research?", completion = "The crystals in this mine are most certainly unique. Thorough study of the samples you have provided should reveal why this is the case.", objectives = "Collect 10 Unrefined Power Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34406] = { id = 34406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Caught In The Chaos", description = "Not all of the Draenei miners made it out when the chaos erupted, {name}. Many of them are injured and still trapped inside the mine.\n\nKaelynara's disruption has caused all hell to break loose. Arcane Wraiths are forming from the unleashed energy and attacking everything they see. The elementals that slumbered beneath the ground are emerging from the rocks frenzied and dangerous.\n\nPlease find as many injured miners as you can and ensure that they return safely.", completion = "Thank you for getting the workers our of the mine safely, {name}.", objectives = "Rescue 8 Injured Miners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34407] = { id = 34407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holding the Line", description = "It is good to see you again, champion.\n\nDemons are assaulting Auchindoun and we are barely standing our ground against them.\n\nWe need to push our front lines forward lest our losses reach critical mass.\n\nIf your blade is with us, shove it into these foul creatures' throats.", completion = "I only hope we are enough.", objectives = "Slay 15 demons in the Burning Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34409] = { id = 34409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Crows In The Field", description = "Our druids set up a wide network of scouts to follow up on your intel from Nagrand.\n\nWe've identified a suspicious Iron Horde excavation near some salt pools on the western coast of Gorgrond.\n\nWe have reason to believe that these orcs are pursuing a valuable artifact deep in the desert.\n\nI'm putting together a small mission for a focused, surgical strike. I'd like you to be part of that team.", completion = "Greetings, {class}. You're the commander from the garrison?\n\n\n\nGood.", objectives = "Speak to Thisalee Crow at Skysea Ridge in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34410] = { id = 34410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Beating Heart", description = "One thing is certain. We now possess an item of great value to the Iron Horde.\n\nWe had better secure this... \"Heart of Gorgorek\" at once.", completion = "Never in my years have I seen anything like this, {name}. You have done well today.", objectives = "Deliver the Heart of Gorgorek to Morthis Whisperwing at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34411] = { id = 34411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Treasure: King Slime" }
quests[34412] = { id = 34412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creature Treasure: Gnarljaw" }
quests[34413] = { id = 34413, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumberstruck", objectives = "Protect your peasants as they gather 100 lumber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34414] = { id = 34414, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An'dure The Giant", description = "In order to break through Kaelynara's arcane shield, we will need a focusing crystal of rare power and quality.\n\nWithin the mine is a crystal giant known to the Draenei as An'dure. The giant has slept beneath the rocky earth for ages, but due to Kaelynara's recklessness it has awakened.\n\nThe heart of a crystal giant is a truly powerful artifact. Defeat An'Dure and return to me with a crystal giant heart. Once I have the heart, I will have everything I need to construct the focusing crystal!", progress = "Do you have the crystal giant heart?", completion = "Excellent. Give me a moment and I will prepare the focusing crystal.", objectives = "Retrieve the Crystal Giant Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34415] = { id = 34415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An'dure The Giant", description = "In order to break through Kaelynara's arcane shield, we will need a focusing crystal of rare power and quality.\n\nWithin the mine is a crystal giant known to the Draenei as An'dure. The giant has slept far beneath the earth for ages, but due to Kaelynara's recklessness it has awakened.\n\nThe heart of a crystal giant is a truly powerful artifact. Defeat An'Dure and return to me with a crystal giant heart.\n\nWhen you return I will construct the focusing crystal and together we will stop Kaelynara.", progress = "Do you have the crystal giant heart?", completion = "It is sad to see such a mighty creature fall, but An'dure was a danger to all within the mine. The heart of the crystal giant will aid us in restoring peace to the Jorune Mine.", objectives = "Retrieve the Crystal Giant Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34418] = { id = 34418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holding the Line", description = "Auchindoun is under attack!\n\nThe Auchenai are valiant warriors in their own right, but they cannot hold against these endless demon hordes alone. We came here to stop the Legion from engulfing Draenor... working together is our best shot.\n\nI need you to thin out the demons' numbers so we can regroup our forces safely and push forward into the Burning Front.\n\nWe will stop their march here and now!", completion = "Your valor will give our men reprieve as they work to contain the threat completely. Well done.", objectives = "Slay 15 demons in the Burning Front.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34420] = { id = 34420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cost of War", description = "They called this operation a suicide mission, but I don't plan on throwing away any lives meaninglessly.\n\nEverybody, with me!", completion = "With the Dark Portal disabled, we have a new mission: stay alive.\n\nWe must keep pressing on, even if only to honor those who stayed behind to secure our retreat.", objectives = "Follow Archmage Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34421] = { id = 34421, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bled Dry", description = "<The orc spits out his last words.>\n\nThey kept us in cages. They... drain our blood, for... rituals...\n\n<The Frostwolf coughs violently.>\n\n...many left --\n\n    -- my... people...\n\n<The orc dies.>", completion = "Well done, {name}.\n\nGiven, they are injured, half-starved, and poorly-equipped... but there is no blade so sharp as a vengeful spirit, no armor so thick as a righteous cause.", objectives = "Free the slaves from the 2 Bleeding Hollow Cages in Heartblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34422] = { id = 34422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blaze of Glory", description = "We can't stay here forever. We NEED to keep moving. But first - we need a distraction.\n\n<Khadgar conjures a small gem.>\n\nThis bead should burn anything flammable that you get close to. With your skill, and a bit of luck, you might be able to take the attention of the Bleeding Hollow orcs off our group.", progress = "We cannot hold out here forever, {name}.", completion = "Out of the frying pan, into the woods.\n\nTake a breath, then get ready, {name}. There's not much time to rest.", objectives = "Use the Lucifrium Bead to destroy 8 Bleeding Hollow huts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34423] = { id = 34423, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Altar Altercation", description = "You see that altar down there? There's a magical eye settled at its peak, and I fear our group will not survive if it sees us.\n\nDistract the eye, {name}. Cause a commotion, kill some ritualists, whatever you have to do - just occupy that thing long enough for me to guide the rest of our group past its gaze.\n\n<Khadgar looks over his shoulder.>\n\nBring that strapping orc with you. The one that's not Thrall.", completion = "<Khadgar looks concerned.>\n\nNo - we cannot wait for Ariok. He knew what he was getting into.\n\nHis sacrifice cannot go to waste. We must keep moving.", objectives = "Speak with Ariok, then help him distract the Eye of Kilrogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34424] = { id = 34424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Chase is On", description = "Come on, let's move! Ariok's heroism can only buy us so much time.", objectives = "Get to the Kargathar Proving Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34425] = { id = 34425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kargathar Proving Grounds", description = "The orcs in this area look like members of the Shattered Hand clan. You can tell by looking at their hands.\n\nLet's join up with the others. We must find a way out of here.", progress = "Yes?", completion = "We will hold this position for now. We must allow these freed prisoners a moment to breathe.\n\nIt is not an ideal position. We will be moving again shortly.", objectives = "Follow Khadgar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34426] = { id = 34426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yrel" }
quests[34427] = { id = 34427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Potential Ally", description = "One of the captured orcs is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the amusement of his captors.\n\nUse this runestone. It should handily deal with the ring of fire that surrounds him.", completion = "I owe my life to you, stranger. I offer you and your company my support. Together, we may make it out of this jungle alive.", objectives = "Use the Frostflurry Focus near the ring of fire in Kargathar Proving Grounds to free Farseer Drek'Thar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34429] = { id = 34429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Your Hundred", description = "I see only one way out of this trap, {name}, and it's right through the middle of that arena.\n\nThis might be the end of us.", completion = "You're still alive? Good.\n\nThat cave-in will only hold them for so long. We have to keep moving.", objectives = "Survive Kargath's Arena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34431] = { id = 34431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masters of Shadow", description = "The bad orcs tried to catch me, but I snuck away. I'm good at hiding.\n\nAll of the bad orcs are bad, but I've remembered the names of the meanest ones, just in case anybody came to save me.\n\n<Luuka takes a deep breath.>\n\nUngra, Gurran, and... umm... oh! Ankova.\n\nWill you protect me from them?", progress = "How goes your mission?", completion = "Well done.\n\nBe ready to move. We may have had the element of surprise within this cave, but our advantage is fleeting.", objectives = "Slay Ungra, Taskmaster Gurran, and Ankova the Fallen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34432] = { id = 34432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadowmoon Clan", description = "We will protect the wounded prisoners and make sure Kargath doesn't get through the rubble. You go ahead and clear the cave, {name}.", completion = "You fight exceptionally well, {name}... better than I could ever hope to.\n\nWith those orcs out of the way, Khadgar and Maraad should now be able to safely guide the rest of our group through the cave.", objectives = "Slay 10 Shadowmoon Orcs or Void Wolves within the Umbral Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34434] = { id = 34434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yrel", description = "Forgive me if I'm a bit flustered - I've never killed anyone before.\n\nMy name is Yrel, and I am a student of Karabor.\n\nYou say you have an ARMY with you? The Light must truly be watching over me today.\n\nI will follow you, then. Lead the way, {name}.", completion = "Up there - that is Keli'dan the Breaker. No doubt he's been alerted to our presence, and he's attempting to tell his warlord about our little jailbreak.\n\nWe have to take him out, {name}.", objectives = "Escort Yrel to safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34435] = { id = 34435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Ga'nar" }
quests[34436] = { id = 34436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keli'dan the Breaker", description = "One of Ner'zhul's lieutenants remains, up ahead. The exit to the cave isn't much farther past him.\n\nI will go back and tell Khadgar that the cave is clear. We will rendezvous once you've taken care of Keli'dan!", completion = "Fine job in the cave, but this is no time to rest.\n\nWe have momentum. We must stay in motion.", objectives = "Slay Keli'dan the Breaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34437] = { id = 34437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prodigal Frostwolf", description = "I can get back to Drek'Thar myself... after I run this stinking shovel through a few Blackrock stomachs.", completion = "You have my thanks, {name}. Durotan, our chieftain, will be happy to hear that Ga'nar lives.", objectives = "Report to Farseer Drek'Thar at the Blackrock Quarry in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34438] = { id = 34438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regarding Enormous Tanks" }
quests[34439] = { id = 34439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of the Forge", description = "Our troops are armed - the time to strike is now!\n\nStrike swift and true, {name}!", progress = "This dam thing is tougher than it looks.", completion = "It's a good thing you got to high ground.\n\nLook at the dam!", objectives = "Slay 15 Blackrock Orcs and 3 Ogron Warcrushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34440] = { id = 34440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Khadgar out of Portal" }
quests[34441] = { id = 34441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fewer, the Merrier", description = "We're vastly outnumbered down here, but at least we have the element of surprise.\n\nFor now.\n\nEvery Blackrock orc we slay in this quarry reduces the probability that we will be overwhelmed later. Go, and thin their ranks before they thin ours.", objectives = "Slay 12 Blackrock Grunts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34442] = { id = 34442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ga'nar of the Frostwolf", description = "We must move on, there isn't time to waste!\n\nOne of the elders of my clan, Ga'nar, is out there somewhere. I can sense him, but I cannot find him.\n\nKeep an eye out for Ga'nar. He is a strong-willed orc, and will languish in captivity.", completion = "<The orc's lips and wrists quiver with restrained fury.>\n\nWho are you?\n\nWait, what's that you say? Drek'Thar is here?", objectives = "Find Ga'nar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34445] = { id = 34445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Taste of Iron", description = "The way I see it, there's two ways to keep this tank from going through the portal: break the tank, or USE the dang tank ta' BLOW UP the dang portal.\n\nI can get 'er workin', I just need time. Hop in that turret off the starboard bow and keep 'em off my back.", progress = "Almost there, {name}.", completion = "Takin' away Gul'dan was one thing, but blowin' up the whole damned portal? That's my kind of solution.\n\nNow, I think we'd better get out of here before that army gets to us.", objectives = "Enter the Worldbreaker Side Turret and destroy 200 Iron Horde troops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34446] = { id = 34446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Home Stretch", description = "If they weren't angry before, they sure are now. We won't survive a minute up on top o' this tank!\n\nLet's join up with the rest and get out of here!!", completion = "Against all odds, here we stand. Still alive, an entire army on our heels.\n\nOur ship is waiting. Shall we depart?", objectives = "Get to the docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34447] = { id = 34447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaelynara Sunchaser", description = "The focusing crystal is complete, {name}. When you are ready I will use the crystal to shatter Kaelynara's shield.\n\nHowever, it is unsafe to confront her within the mine. The moment her shield is down I will teleport us to a safe location outside of the Jorune Mine. She will be much easier to deal with when she is far away from the crystal.\n\nSpeak with me when you are ready to begin.", progress = "Are you prepared to end Kaelynara's madness?", completion = "A wise elder of my order once told me, \"True power is the strength to act and the wisdom to know when not to act.\" May those words and the memory of Kaelynara stay with you on your journey, {name}.", objectives = "Confront Kaelynara Sunchaser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34448] = { id = 34448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaelynara Sunchaser", description = "The focusing crystal is complete, {name}. When you are ready I will use the crystal to shatter Kaelynara's shield.\n\nHowever, it is unsafe to confront her within the mine. The moment her shield is down I will teleport us to a safe location outside of the Jorune Mine. She will be much easier to deal with when she is far away from the crystal.\n\nSpeak with me when you are ready to begin.", completion = "A wise elder of my order once told me, \"True power is the strength to act and the wisdom to know when not to act.\" May those words and the memory of Kaelynara stay with you on your journey, {name}.", objectives = "Confront Kaelynara Sunchaser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34450] = { id = 34450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rylak Rescue", description = "I managed to squeeze even more information out of our little friend here.\n\nThe Darktide Matriarch is at the top of the hill.\n\nOne of their lead engineers is attempting to tame the matriarch with his technology. We must stop him, {name}.", completion = "We have accomplished great things on this island today, {name}. I look forward to the day we hunt again.", objectives = "Kill Razz Ricketroz at Darktide Roost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34451] = { id = 34451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sunsworn Camp", description = "We no longer have a need to work alongside the Auchenai, champion. I have arranged for their lead soulbinders to continue to advise us, but I believe any action is best left to us at this point.\n\nMeet me at Sunsworn Camp, southeast of here. I can sense more demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", completion = "There is still much to be done before we can leave Auchindoun with peace of mind, champion.", objectives = "Meet Lady Liadrin at Sunsworn Camp in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34452] = { id = 34452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Light's Rest", description = "With the brute force of our enemy neutralized, we must turn our sights on quelling the aftermath and preparing for any future assaults. We still need Auchindoun's defenses reinvigorated.\n\nMeet me at Light's Rest, not far south of here. We have reports coming in of demonic taint in the area, and we may be able to track down the remaining power crystal shards at its source.", completion = "We have our work cut out for us, champion. The Legion's stench fills the air.", objectives = "Meet Exarch Maladaar at Light's Rest in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34453] = { id = 34453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Gazlowe Arrived" }
quests[34454] = { id = 34454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mind Controlled Rylaks", description = "xxxxx" }
quests[34455] = { id = 34455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free their Minds", description = "This device is what the goblins are using to control the rylaks.\n\nThere is a button on the controller labeled do not touch.\n\nGet within range of a Controlled Rylak and touch the button.", objectives = "Use the Rylak Mind Controller on Controlled Rylaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34456] = { id = 34456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirit of the Wolf" }
quests[34457] = { id = 34457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonus Objective: Ogron-Be-Gone" }
quests[34458] = { id = 34458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Defenses", description = "What few soulpriests we don't have on the front lines are working fervently to maintain Auchindoun's defenses. They aren't going to be able to keep it up much longer alone.\n\nSoulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. I need you to find her and get her and the pylon back here safely.", completion = "You look like you can fight. We need to get out of here!", objectives = "Find Soulbinder Tuulani in the Tomb of Lights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34459] = { id = 34459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Defenses", description = "I know what the Bonechewer are after.\n\nAuchindoun is protected by a powerful barrier, which can only be disabled using an ancient key. No being could ever hope to penetrate it.\n\nThe Auchenai, my people, split the key into three shards long ago and hid each piece outside the mausoleum walls. We guard those shards with the same zeal as Auchindoun itself.\n\nGo into the Tomb of Souls and retrieve the key from Soulbinder X. The shards are no longer safe.", sourceObjective = "Retrieve the Shard of Souls in the Tomb of Souls.", sourceObjectiveStatus = "unverified-source-field" }
quests[34461] = { id = 34461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build Your Barracks", description = "You are going to want to build your barracks, which you're gonna need to properly bash faces.\n\nThe first step is to go find the blueprints and learn 'em. I think I left some blueprints lying around here somewhere.\n\nNext ya gotta pick which plot you want us to build it on. Just point it out on my architect table and we'll get started constructing that thing right away.", progress = "You pick the plot, we'll build the spot!", completion = "This will be a mighty fine barracks, I think. I am sure Warmaster Zog will complain about how it needs to be bigger, and with more spikes. He likes spikes...", objectives = "Find and learn the Garrison Blueprints: Barracks and then use the Architect's Table to build your barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34462] = { id = 34462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winds of Change", description = "Commander, I have bad news. Olin Umberhide, the tauren who escaped with you from Tanaan, was ambushed when near the eastern perimeter of the Garrison.\n\nHe was seen being dragged off by the pale. These are dangerous, disturbing creatures that some believe were once orcs. Now they are husks of barely living flesh bent by dark magics.\n\nOlin is resourceful, but outnumbered. I would advise travelling east to effect a rescue as soon as possible, before they eat him alive... slowly.", progress = "Have you found Olin? Was he alive or dead?", completion = "Well done, commander. Olin spoke to me of your bravery and has already offered to serve under your command.\n\nIf I may advise you in this matter, I would suggest accepting his service. We could make use of a tauren with his skill set in a land like this.", objectives = "Rescue Olin Umberhide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34463] = { id = 34463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Ring", description = "This elegantly crafted ring is covered in ornate decorations and symbols, the most prominent of which being the letter \"V\" in a glowing rune. The ring seems to fade in and out of view as if passing back and forth through time.\n\nSomeone at Khadgar's Tower may have an interest in such an artifact.", progress = "Time magic is a young field of research.", completion = "Ah. Now what do you have there? This ring is going to require some extra research.\n\nIt seems like someone was trying to travel through time but in a very backward fashion.", objectives = "Bring the Mysterious Ring to Zooti Fizzlefury at Khadgar's Tower in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34464] = { id = 34464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Boots", description = "Phasing back and forward in time, these flickering ornate boots are adorned with a lavish \"V\" on them.\n\nSomeone at Khadgar's Tower might have insights to the nature of these strange items.", progress = "I was wondering \"when\" I would see you again. Ah...? Ah...? Get it?\n\nLook, for as long as anyone was speaking the bronze dragons got to hog all of the good time jokes.\n\nWell now the guardians of time are taking a break and there is no one left to stop me!", completion = "These boots are fantastic! You did the right thing bringing these to me.\n\nThey are actually trying to replace the space they occupy with a different timeline.\n\nThis will definitely require more study.", objectives = "Bring the Mysterious Boots to Zooti Fizzlefury at Khadgar's Tower in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34465] = { id = 34465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Hat", description = "Energy flows from this mystical hat with an unseen strength. It hums as it drifts back and forward in time where it rests on the ground.\n\nThis is the sort of object that someone at Khadgar's Tower would find very interesting.", progress = "It is so nice to finally be able to research my passion without those interfering bronze dragons showing up.", completion = "Now THAT is a hat. See how it flickers in and out of time as if someone were temporally jiggling it?\n\nI'd try putting it on if I weren't afraid it would wipe me from the timeline.", objectives = "Bring the Mysterious Hat to Zooti Fizzlefury at Khadgar's Tower in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34466] = { id = 34466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Staff", description = "Fluctuations in reality surround this staff so much that it is hard to identify any recognizable markings aside from a large, lavish \"V\" on its apex.\n\nThis might require help to identify by someone from Khadgar's Tower.", progress = "I did my time with fire and the other arcane arts. They were good. Nothing compares to hurling a giant ball of fire.\n\nBut temporal wizardry? So much fun!\n\nReally hard to master but you always have plenty of time.", completion = "Hmm. This staff looks familiar. I wonder...\n\nYou did the right thing bringing it to me. I will investigate further!", objectives = "Bring the Mysterious Staff to Zooti Fizzlefury at Khadgar's Tower in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34469] = { id = 34469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing the Souls", description = "Not all spirits are destroyed by the Soulgrinder. Some souls manage to survive more or less intact like myself. Others have become twisted and maddened.\n\nEnd their misery, take my soul shard and use it to purify them. Their rage will blind them to the effects of its energy so you must defeat them before you use it.", completion = "Thank you, I am glad that the spirits have been released from their torment.", objectives = "Cleanse 10 Crazed Souls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34470] = { id = 34470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Pale Gone Fishin'" }
quests[34471] = { id = 34471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Bright Coin" }
quests[34472] = { id = 34472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temporal Juxtaposition", description = "I think I figured out what those mysterious artifacts you collected were for.\n\nIt would seem someone is attempting to affect a temporal shift by sending items back into this timeline from your own timeline.\n\nTechnically that shouldn't be possible. But whoever this is found a way.\n\nI think I may try a ritual to bring the traveler through.", completion = "{name}? Is that you? Fantastic! And they said it couldn't be done.\n\nThey said traversing the worlds in this way was the domain of the bronze dragonflight. Well, guess who's temporally laughing now!", objectives = "Wait for Zooti Fizzlefury's temporal ritual to complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34473] = { id = 34473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Envoy's Log" }
