quests[34475] = { id = 34475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Invasion!", description = "Your garrison is under attack!  Use this magic device to get back there and defend it!", objectives = "Speak with Sergeant Grizzleface in your garrison.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
