quests[34478] = { id = 34478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Potential Ally", description = "One of the captured draenei is receiving some... preferential treatment, if you can call it that. While others are tied down and tortured, this one is tied to a stake and burned for the orcs' amusement.\n\nUse this runestone. It should handily deal with the ring of fire that surrounds this draenei.", completion = "I owe my life to you, stranger. I offer you and your company my support. Together, we may make it out of this jungle alive.", objectives = "Use the Frostflurry Focus near the ring of fire in Kargathar Proving Grounds to free Exarch Maladaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
