quests[34507] = { id = 34507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Frozen Frostwolf Axe" }
quests[34508] = { id = 34508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restalaan, Captain of the Guard", description = "They killed Aedraa and took the crystal from her! The captain of the guard, Restalaan, tried to stop them and they took him into the cathedral!\n\nIf we can just get this crystal, we can reunite the Heart of Auchindoun and turn its defenses on fully! We can't afford to fail now.\n\n{name}, you're the only one left that can do it. You have to find Restalaan! He'll know where they took it.", completion = "There is no time for pleasantries. The raid's leader is just ahead.", objectives = "Find Restalaan in Telmor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34509] = { id = 34509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Jaws of the Jungle", description = "We've freed enough prisoners that I feel we're strong enough to move forward as a group. We cannot stay here long - Grommash Hellscream will be on our tail soon enough.\n\nLet me know when you're ready, and we'll press on.", objectives = "Move further into Heartblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34510] = { id = 34510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Catapults 'n' Clefthoof" }
quests[34511] = { id = 34511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Ogre Drag" }
quests[34512] = { id = 34512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Declawing The Competition", description = "These saberon freaks have cost me a lot of money, {class}.\n\nI'm not one to forgive a debt and it's time to collect!\n\nThe saberon that have been causing us the most trouble are the ones living in Sabermaw. They keep ambushing our trade shipments along the road.\n\n<Pyxni grins.>\n\nIt's time to declaw the competition. Bring me their claws; we'll sell the best ones as good luck charms here at the arena.\n\nIf the claw sales don't cover their debt, we'll just have to charge them an arm and a leg too!", progress = "Do you have the saberon claws I asked for?", completion = "<Pyxni examines the saberon claws.>\n\nWe're gonna make a killing selling these as good luck charms to all the wannabe gladiators here at the arena!\n\nFrom now on, the saberon will think twice about messing with the Steamwheedle Cartel!", objectives = "Collect 10 Saberon Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34513] = { id = 34513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Razorpaw!", description = "Wanted for crimes against the innocent at the Ring of Trials!\n\nRazorpaw is responsible for leading several raids and ambushes against travelers on the road near Sabermaw.\n\nLast seen in the vicinity of the saberon den known as Sabermaw.\n\nExercise extreme caution!\n\nUpon completion, this bounty will be fulfilled by Pyxni Pennypocket of the Steamwheedle Cartel.", completion = "You fought your way into Sabermaw, killed Razorpaw...and lived?\n\nThat's incredible news!\n\nThe roads will be much safer now that he's dead! That means more money for me!\n\nAs promised, here's your reward!", objectives = "Defeat Razorpaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34514] = { id = 34514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They've Got The Goods!", description = "The Saberon...they weren't just after prisoners...\n\n<Cough>...they took all the merchandise too.\n\nKidnapping is one thing...but stealing a goblin's merchandise? That's making things personal!\n\n<Cough>...Pyxni ain't going to be happy unless you get all of the stolen goods back. Make your way into Sabermaw and steal back all our merch.\n\nWhen you're done, make your way back to Pyxni at the Ring of Trials.\n\nShe'll make it worth your while...", progress = "Greexlex told you that the saberon stole our merchandise?\n\nWell, what are you standing around for? Get your butt over to Sabermaw and get it back!\n\nTime is money!", completion = "You recovered the merchandise? Fantastic!\n\n<Pyxni rummages through the bags.>\n\nIt's all here too! I knew I could count on you! Here, take this reward.\n\nYou've earned it!", objectives = "Recover 10 Stolen Goods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34515] = { id = 34515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gobnapped", description = "We never even saw the ambush coming...\n\nThe saberon hit us so hard and fast we barely had time to think.\n\nThose overgrown mongrels dragged the others away and left me here for dead...they probably thought I was too close to dying.\n\nI hear they like their meat fresh...\n<cough>....well I ain't going down that easy!\n\nDon't worry about me...<cough>...I've been through worse! You're gonna have to go to Sabermaw and get the other merchants out though.\n\nThey've probably got 'em all caged up in there...", completion = "You got all of the captured traders out of Sabermaw? Fantastic!\n\nNow they owe me and I ain't one to let a debt go uncollected! As for you, take this reward for your trouble!", objectives = "Rescue 6 Goblin Traders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34516] = { id = 34516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Precious!", description = "You've got to help me!\n\nI was hiding on the trade wagon that got ambushed just down the road from here. I snuck away before the saberon spotted me...but...but...\n\nTHEY STOLE MY MOST PRIZED POSSESSION!\n\nYou've got to help me get it back! I watched them drag it into Sabermaw and up that giant hill!\n\nWho knows what those filthy saberon will do to it!\n\nPlease, I'm just a kid! You've got to help me out, right?", completion = "You did a great job, {name}. I couldn't have asked for a better sidekick!\n\nAnyway, now that I've got my treasure back...\n\nI've got to do...\n\n...things and...stuff.\n\nBye!", objectives = "Find Bazwix's stolen treasure.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
