quests[34532] = { id = 34532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tearing Up Talador", description = "Commander, we have a bit of a problem.\nWe found a location in Talador to set up an outpost but the team that was sent to begin construction have been arguing with each other on what to build. This situation could really put a setback in our plans unless it's dealt with swiftly.\n\nTake a gryphon to Talador and speak with Foreman Eksos before this gets any worse." }
