quests[34557] = { id = 34557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Treasure Map" }
quests[34558] = { id = 34558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At Your Command", description = "I'm glad you're here!\n\nFort Wrynn is nearly complete. We only need to fill this last plot.\n\nBaros provided us with blueprints for two different structures that would fit this space - an Artillery Tower or an Arcane Sanctum.\n\nIt's your call, commander. The plans are on the drafting table for your perusal.", progress = "At your command.", completion = "Excellent. This will do nicely.", objectives = "Choose which outpost structure to construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34559] = { id = 34559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Yaga the Scarred", description = "Goren are dangerous, especially in large numbers, and especially when we have a blind, under powered shaman with us.\n\nFortunately, they have very short lifespans. Unfortunately, they multiply fast and grow faster.\n\nIf we are going to do this we need to find the brood mother. Slaying her and her eggs should slow down the onslaught of goren. Check the burrows near the Forge Gates and I will to keep them off of Drek'Thar's scent." }
quests[34560] = { id = 34560, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armory" }
quests[34561] = { id = 34561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Tower" }
quests[34562] = { id = 34562, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trigger Teron'gor Defense Spawns" }
quests[34563] = { id = 34563, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quarry Quandary", description = "Now that we have the artillery tower built, we're going to need some skilled hands to run it.\n\nI've heard that Ared, one of the best smiths in Shattrath, managed to escape the city's fall. He should be just outside the north wall with the rest of the refugees.\n\nSee if you can convince him to work for us.", progress = "We need to find someone to run this place or we're not going to be producing much of anything.", completion = "You are the commander of this fort, yes?\n\nMy master wanted to join your fight to reclaim our home but he grew ill and... I'm sorry, he was a great draenei and I will carry on his memory.\n\nYour new building would give me the means to see out my master's vision and honor his passing.\n\nIf you would allow me to do this then I would serve you.", objectives = "Speak to Apprentice Miall just outside of Fort Wrynn in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34564] = { id = 34564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destination: Unknown", description = "Teron'gor and Gul'dan were just leaving through the portal as I arrived... and I... I know I won't be able to defeat them.\n\nI'll hold open the portal as long as I can. It will be up to you to strike the killing blow.\n\nOur fate is in your hands, {name}.", completion = "Teron'gor and Gul'dan... they slaughtered everyone...\n\n...and then they just... disappeared... into the shadows...\n\nHow did they know where to go?", objectives = "Destroy Mongrethod in the Remains of Xandros.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34565] = { id = 34565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tearing Up Talador", description = "Commander, we have a bit of a problem.\n\nWe found a location in Talador to set up an outpost but the team that was sent to begin construction have been arguing with each other on what to build. This situation could really put a setback in our plans unless it's dealt with swiftly.\n\nTake a gryphon to Talador and speak with Foreman Eksos before this gets any worse." }
quests[34566] = { id = 34566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At Your Command", description = "Commander, the outpost is nearly fully operational.\n\nGazlowe provided us with two different blueprints to fill this final plot - an Arsenal or an Arcane Sanctum.\n\nEither one would provide us with the additional firepower we need to stop the Iron Horde's advance.\n\nThe plans are on the drafting table. It's your call.", progress = "What is your will, commander?", completion = "Your will be done.\n\nFor the Horde!", objectives = "Inspect the Drafting Table and choose which outpost structure to construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34567] = { id = 34567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Tower" }
quests[34568] = { id = 34568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armory" }
quests[34569] = { id = 34569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Quarry Quandary", description = "Now that our arsenal is built we need a skilled smith to operate it.\n\nWe recently caught an Iron Horde deserter who claims he used to be one of the Blackrock's best iron workers.\n\nNormally I'd ignore the ravings of a captive, but the weapons we took out of his pack had the finest workmanship I've ever seen.\n\nCommander, I think we should see if he's as good as he claims.", completion = "You're the one in charge around here, right? I've heard the guards talk about your exploits and if I wasn't looking at you now I'd swear they were lying.\n\nI've only ever wanted to make the finest blades and put them in the hands of the strongest of fighters. I can tell already that you're exactly the type I want to carry my weapons.\n\nIf you can give me a chance I swear you will not be disappointed.", objectives = "Obtain Morketh Bladehowl's assistance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34570] = { id = 34570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "Teron'gor and his master Gul'dan were here! I tried to stop them... they escaped through the demonic gateway behind me before I could finish them!\n\nI think I can activate the portal open just long enough for you to enter. We have no way of knowing where it leads, but I fear it may end inside Auchindoun!\n\nYou have to stop him once and for all!", objectives = "Slay Hurkan Skullsplinter in the Seat of Depravity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34571] = { id = 34571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Jovite", description = "Ared and I came this way because we needed a good supply of metal to build his designs and some of the best metal is the jovite that comes from the mine in Kuuro's Claim. In order to supply the artillery tower I'm going to need this metal.\n\nUnfortunately that place was recently overwhelmed by a pack of goren, so you're going to have to fight your way in to get the ore before they manage to devour it.\n\nNothing that should be too much of a problem for you.", progress = "We need to get that ore before those goren eat it all.", completion = "These look pretty good. Ared would have loved to get his hands on these.\n\n<Miall wipes away a tear.>\n\n I'm sorry, this is making me too emotional, these will do just fine.", objectives = "Obtain 12 chunks of Jovite Ore from within Kuuro's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34572] = { id = 34572, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obliterating Ogres", description = "With actual ogre mages present, the Highmaul have been increasing patrols and aggression.\n\nThinning their ranks will go a long way to deterring the Highmaul from making a comeback in Nagrand.\n\nHead up to my sister Mirana afterwards, she should have more news.", completion = "Perfect, they will have to concentrate more on base defense now.  Hopefully things will get back to normal out there.", objectives = "Kill 15 ogres at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34573] = { id = 34573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iridium Recovery", description = "Ared used to always teach me that the purity of the metal is key. If the metal isn't pure it will crack under stress and be of no use to anyone.\n\nFor the artillery tower to function I'll need to make metal as pure as my master would, and for that I need a strong flux.\n\nThe dust from crushed iridium geodes would work in a pinch, but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", progress = "I'm going to need a lot of iridium dust to purify the metal to anywhere near my masters standards.", completion = "This won't be as good as some of the stuff we had back at the forge in Shattrath, but it will do.", objectives = "Gather 8 Iridium Dust from Iridium Geodes in Kuuro's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34575] = { id = 34575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Step Three: Prophet!", description = "You have arrived in Shadowmoon Valley. It is time to speak with the prophet.", completion = "<The prophet welcomes you with a curious look, then a warm nod.>\n\nSo it begins.", objectives = "Speak with Prophet Velen near the crashed Iron Horde Ship in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34576] = { id = 34576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iridium Recovery", description = "My goods used to be for the very best, now the Iron Horde make copies out of poor metal and give them to everyone.\n\nI'm going to show them what a real smith can do in your arsenal, but first I'm going to need a powerful flux to make the metal as pure as it can get.\n\nThe dust from crushed iridium geodes would work in a pinch but we need to find some first. They tend to congregate underground, so check out the mine in Kuuro's Claim nearby.", progress = "I'm going to need a lot of iridium dust to purify the metal to anywhere near my standards.", completion = "This won't be as good as some of the mixes we had back in the Blackrock foundries, but it will do.", objectives = "Gather 8 Iridium Dust from Iridium Geodes in Kuuro's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34577] = { id = 34577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Jovite", description = "Crafting good equipment requires the best metal and some of the best metal is the jovite that comes from the mine in Kuuro's Claim, just east of here. In order to supply the arsenal I'm going to need this metal.\n\nUnfortunately the place was recently overwhelmed by a pack of goren so you're going to have to fight your way in to get the ore before they manage to devour it.\n\nNothing that should be too much of a problem for you, <sir/ma'am>.", progress = "We need to get that ore before those damned goren eat it all.", completion = "Good size chunks and without a lot of the matrix material on them.\n\nThese will do just fine.", objectives = "Obtain 12 chunks of Jovite Ore from within Kuuro's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34578] = { id = 34578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going to the Gordunni", description = "We have a good supply of jovite now but there just isn't enough of the material in the mine to keep the artillery tower in stock for long. Down south of here there's a mountain that's just full of the stuff but there's one problem; Ogres!\n\nThe Gordunni live on top of that mountain and they have begun trading the jovite to the Iron Horde.\n\nWe need to go down there and secure the minerals for ourselves.\n\nI'll pack some supplies and meet you near their fortress down south.", completion = "I crafted a few things before we left that we may need: some smoke grenades, a grappling hook, even was able to get Thaelin to throw together a rocket pack.\n\nI'm sure we'll find a use for everything.", objectives = "Travel to Gordal Fortress and meet up with Miall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34579] = { id = 34579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gas Guzzlers", description = "<Sir/Ma'am>, to make the best equipment for your arsenal I need not only the best materials, but to use the best techniques.\n\nOver the years I've developed a method to greatly strengthen my metal, but it does require an exotic resource: goren gut gas!\n\nThe nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for the arsenal supplies? Just kill a few goren and give their bodies a good prod with this gas extractor.", completion = "Thank you boss, this is just what I needed.\n\nBy the way, Goren gas is rather difficult to come by. We should probably hold off on clearing those guys out till we can stockpile enough.\n\nJust a thought.", objectives = "Obtain 6 samples of Goren Gas from Glowgullet Shardshedders and Glowgullet Devourers within Kuuro's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34580] = { id = 34580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Flowerpicker" }
quests[34581] = { id = 34581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor Flowerpicker Note Found" }
quests[34582] = { id = 34582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finding a Foothold", description = "So, you are the one that has led my children home? I have been waiting for you.\n\nThe Iron Horde grows stronger every day.\n\nI have foreseen a great battle, but my visions are clouded. It's as if time is sitting on top of itself. \n\nOne thing is certain, your presence here is of great importance.", completion = "This will have to do.", objectives = "Follow Prophet Velen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34583] = { id = 34583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For the Alliance!", description = "We wouldn't have survived Tanaan without your strength, {name}. Many draenei and Alliance alike owe you a great debt.\n\nBefore we departed for the Dark Portal, King Wrynn personally recommended that I place you in charge of our operations here in Draenor. After seeing you in action, I'm inclined to agree.\n\nThis is your garrison to found. Plant the banner and we'll begin construction immediately, commander.", completion = "So this is Draenor? A bit darker than expected. Still, after building Stormwind, this project should be a walk in the park.\n\nWell then, are you ready to begin, commander?", objectives = "Plant the Alliance banner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34584] = { id = 34584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking for Lumber", description = "Some of the trees around here look small enough that the workers should be able to down them in no time.\n\nWe can leave the hard labor to Shelly's men, but if you'd be willing to mark the trees for them to start with, we should be able to get this operation rolling much faster.", progress = "How goes the lumber hunt?", completion = "Perfect.\n\nNot only will this lumber do the job, it will look fantastic!", objectives = "Mark 8 trees.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34585] = { id = 34585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quakefist", description = "I'm getting reports of a giant in the forest.\n\nA few of the Karabor peacekeepers have followed it to a cave. In all honesty I don't think any of our troops are willing to engage the beast.\n\nMaybe you could investigate? I'm sure the peacekeepers would appreciate the help.", progress = "Did you kill the giant in the cave?", completion = "The base is significantly more secure with that giant dead.\n\nYou have made quite an impression on the peacekeepers.", objectives = "Kill Quakefist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34586] = { id = 34586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Establish Your Garrison", description = "I'm impressed with how quickly you have pulled this group together, commander.\n\nI think it's time we start putting up some walls and establishing a firm perimeter around our base.", completion = "The garrison is really starting to take shape.", objectives = "Build your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34587] = { id = 34587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build Your Barracks", description = "I must say, commander, this garrison has really come along.\n\nWe have enough materials, all we need now are the blueprints I drafted up and I can begin construction on your barracks.\n\nHmm... now where did I put those blueprints?", progress = "The troops will sleep a lot better tonight.", completion = "How is the construction of the barracks coming along?", objectives = "Find the blueprints, learn the blueprints, and use the Architect Table to build your barracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34588] = { id = 34588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bounty of Bladespire", description = "The sacking of this fortress is as much your victory as ours. It is only fair you should share in the bounty.\n\nI will have resources set aside as we find them. All you need do is report to your garrison and have them dispatch peons to collect these materials.", sourceObjective = "Speak with Gazlowe at your Garrison in Frostfire Ridge", sourceObjectiveStatus = "unverified-source-field" }
quests[34592] = { id = 34592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gronnling Problem", description = "It's gonna be quite a task to build you a fortress if there's gronnlings rampaging around.\n\nI don't think anyone else here can handle taking those big beasts out, so you might need to take care of it yourself.", progress = "If you can't find gronnlings, you ain't lookin' hard enough.", completion = "Nasty beasts they got here on Draenor.", objectives = "Kill 8 Frostfire Gronnlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34593] = { id = 34593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obtaining Ogre Offensive Orders", description = "My sister, Mirana, is scouting the upper bluff while I've checked out the lower area. There are two particular ogre mages that do a lot of bossing around in the lower area.\n\nThey seem to have some orders or scrolls on them that would help us figure out what's really going on.\n\nCollect that information and meet with my sister on the long stairway up there.", progress = "Those orders would be really useful in piecing this whole thing together.", completion = "Glad you are here. I almost got killed up there at the top. Oh what are these papers? This is much worse than I imagined!", objectives = "Collect Crulgorosh's Orders and Thulgork's Orders at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34596] = { id = 34596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reglakk's Research", description = "These ogres have been using ancient Titan artifacts to empower a small cadre of specialized units called the Breakers. This Magister Reglakk is here studying ways to improve the process.\n\nLet's put a stop to whatever rituals he has going up on the bluff.", completion = "That Felbreaker sounded tough! Good thing there's only a small number of them.\n\nNice job stopping Reglakk, but I'm sure he's safely back in Highmaul. The ogre capital will have to be dealt with sooner rather than later.", objectives = "Stop Grand Magister Reglakk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34597] = { id = 34597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Removing the Paper Trail", description = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic.\n\nIt would be best to ruin these efforts by destroying any research found.", completion = "Excellent job thinking on your feet.  The less research these ogres do, the better!", objectives = "Destroy 8 Boxes of Ogre Research at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34598] = { id = 34598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Caravan", description = "I've got a problem and you look like you're just the {race} for the job!\n\nA trade shipment was supposed to arrive yesterday, but it's nowhere to be found. I'm running low on merchandise here and I need somebody to go find out what happened!\n\nIf I were to guess, I'd say the saberon are probably involved. Those brutes have been a pain in our side ever since we got here!\n\nSearch for the wagon on the road near Sabermaw and hurry! Time is money!", completion = "<Greezlex lifts his head to look up at you from the ground.>\n\n...No! Don't take me... I... wait...\n\nYou aren't a saberon... did Pyxni send you?", objectives = "Find the missing trade shipment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34599] = { id = 34599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Yrel Leave Twilight Glade" }
quests[34600] = { id = 34600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Vorka, Rangari Leave" }
quests[34602] = { id = 34602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Goren", description = "xxxxxx" }
quests[34609] = { id = 34609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creating the Ink", description = "We need a way to create an artificial nexus at your tower.\n\nI know where we can get the conduit to do that, but it's well-guarded. We need to keep our cool and do this the right way.\n\nI have a plan - a scroll of mass teleportation.\n\nThe fungal giants and shamblers down below are covered with pustules full of an oily substance. We can use the oil to craft a makeshift ink substitute for the scroll.", progress = "The giants are harder to take down, but they will yield more pustules!", completion = "This isn't quite what they taught me in Dalaran, but it'll have to do!", objectives = "Gather 30 Pulsating Pustules from Sporebats and Fungal Giants in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34612] = { id = 34612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forming the Scroll", description = "We'll need arcane parchment to make the scroll.\n\nThe arcane energy everywhere at this nexus froze the ancients in place and settled in their bark.\n\nIf we take pieces from the few that haven't been destroyed by the fungal creatures, I can mold them into parchment.", completion = "Yes, these will work great! I can freeze the pulp into a fine parchment.", objectives = "Rip 3 Pieces of Bark off of Slumbering Ancients in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34616] = { id = 34616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravenous Ravens", description = "Do you see that? There is a gigantic raven just past the tree line.\n\nI'm not getting anywhere near that. In fact, I'm not sure any of the men are sufficiently equipped to deal with a threat like that. \n\nDo you want to handle this one yourself, commander?\n\nOnce those ravens are gone we can start sending more troops into the woods. So we will be killing two birds with one stone... or should I say kill five birds with...\n\n<Confused by his own analogy, Baros scratches his head.>\n\nYou get the point.", progress = "Did you kill those ravens?", completion = "This place is just full of surprises... terrifying surprises.", objectives = "Kill 6 Lunarfall Ravens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34619] = { id = 34619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Spark", description = "We need arcane energy to complete our scroll. It needs that to coalesce the scroll together.\n\nI have an artifact that can capture energy vortexes in the caldera below, so let's get moving.", progress = "This is why I love magic. It's so... refreshing.", completion = "Perfect! We should have plenty of energy now.", objectives = "Harvest 3 Arcane Vortexes in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34622] = { id = 34622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Ner'zhul Leave" }
quests[34624] = { id = 34624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gas Guzzlers", description = "To complete my master's designs and to stock up the artillery tower we need to use an exotic resource, namely goren gut gas.\n\nThe nearby mine at Kuuro's Claim just came down with an infestation of the things. Could you collect a few samples for me? The stuff is concentrated, so only a few are needed. Just kill one and give its body a good prod with this gas extractor.", completion = "Thank you, this is just what I needed.\n\nGoren gas is rather difficult to come by but thankfully we can make this supply go a long way.", objectives = "Obtain 6 samples of Goren Gas from Glowgullet Shardshedders and Glowgullet Devourers within Kuuro's Claim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34631] = { id = 34631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience With The Archmage", description = "I'm pleased to report that your Arcane Sanctum is up and running, commander!\n\nEverything is exactly as the blueprint says... except for this note Baros scrawled on the bottom. \"Don't forget to connect the sanctum to the ley line network!\"\n\nCommander, I'm a foreman, not a mage. I... have absolutely no idea how to do that.\n\nWe've found Archmage Khadgar and some other Kirin Tor not far from here. To the east, near the mountains. Perhaps we should ask them for a hand?", completion = "Ah, so you've built an Arcane Sanctum! Splendid!\n\nTroubles connecting to the ley line network, I take it?", objectives = "Speak to Archmage Khadgar in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34632] = { id = 34632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Audience With The Archmage", description = "Your Arcane Sanctum is coming along nicely, commander.\n\nEverything's built to spec... except for one detail Gazlowe scrawled in at the bottom of the blueprint. \"Don't forget to connect the sanctum to the ley line network!\"\n\nI, uh... I have no idea how to do that.\n\nI'm sorry commander, but magic just isn't my thing. We did spot Archmage Khadgar and some Kirin Tor not far from here. To the east, up near the mountains.\n\nMaybe we should ask them for help?", completion = "Ah, so you've built an Arcane Sanctum! Splendid!\n\nTroubles connecting to the ley line network, I take it?", objectives = "Speak to Archmage Khadgar in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34633] = { id = 34633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[34634] = { id = 34634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Creating the Ink", description = "We're going to need a way to create an artificial nexus at your tower.\n\nI know where we can get what we need, but it's heavily protected. We don't have the firepower to just waltz in the front door.\n\nI have a plan - a scroll of mass teleportation.\n\nThe fungal giants and spore creatures down below are covered in pustules filled with an oily substance. If we gather enough of the oil I can craft a makeshift ink substitute for the scroll.", progress = "The giants have many more pustules than the sporebats, but are much tougher.", completion = "These pustules are sizzling with energy. They'll do nicely.", objectives = "Gather 30 Pulsating Pustules from Sporebats and Fungal Giants in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34635] = { id = 34635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forming the Scroll", description = "For this plan to work, we'll need infused parchment.\n\nThe latent arcane energy at this nexus quickly froze the ancients in place and settled in their bark.\n\nIf we rip off strips from the few that haven't been destroyed by the fungal creatures, I can form them into parchment.", completion = "Such clean breaks on each piece! Fantastic.", objectives = "Rip 3 Pieces of Bark off of Slumbering Ancients in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34636] = { id = 34636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Spark", description = "We need to get our hands on arcane energy to complete our scroll. It needs that fiery kick.\n\nI have a device capable of capturing energy in the space below, so let's get moving. The infused creatures shouldn't be an issue for the two of us.", progress = "There's so much untapped power... think of the potential!", completion = "Excellent. This ought to be just what we need.", objectives = "Harvest 3 Arcane Vortexes in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
