quests[34645] = { id = 34645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Warmaster Blugthol" }
quests[34646] = { id = 34646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Qiana Moonshadow", description = "If we are to win this war we are going to need more than foot soldiers. We need champions.\n\nQiana Moonshadow's performance in Tanaan and Eventide Landing was quite impressive.\n\nPerhaps you should speak with her about taking on a greater role in the battle against the Iron Horde.", completion = "Luuka is a little shaken up, but he is safe, and that's all that really matters.\n\nLook... commander, I owe you my life. All of us do honestly.\n\nI would be honored to serve as your agent here in Draenor. If you have need of me, you need only say the word.", objectives = "Speak with Qiana Moonshadow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34647] = { id = 34647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette/Treasure: Snow-Covered Strongbox" }
